/** * WakeOnLan Win10 (Custom) * Platform: Hubitat Elevation * Notes: Parent container app managing Wake-on-LAN target child apps. * Category: Utility **//** * Copyright 2026 James Shimota * * Licensed under the Apache License, Version 2.0 (the "License"); * you may not use this file except in compliance with the License. * You may obtain a copy of the License at: * *     http://www.apache.org/licenses/LICENSE-2.0 * * Unless required by applicable law or agreed to in writing, software * distributed under the License is distributed on an "AS IS" BASIS, * WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied. * See the License for the specific language governing permissions and * limitations under the License. **//** *  Purpose: *  Parent app container that spawns and manages child app instances for individual WOL targets. * *  Changelog: *  v1.1.0   09/17/26   jshimota   Refactored to Parent/Child App architecture for nested UI hierarchy on Apps page. **/static String version() { return '1.1.0' }def timeStamp() { return "2026/09/17 09:00 AM" }definition(    name: "WakeOnLan Win10 (Custom)",    namespace: "jshimota",    author: "James Shimota",    description: "Manage and trigger Wake-on-LAN magic packets across LAN targets.",    category: "Utility",    iconUrl: "",    iconX2Url: "",    iconX3Url: "",    singleInstance: true,    importUrl: "")preferences {    page(name: "mainPage")}def mainPage() {    dynamicPage(name: "mainPage", title: "", install: true, uninstall: true) {        String currentVersion = version()        /* Header Banner */        section() {            paragraph "<div style='background-color:#1A252F; color:#FFFFFF; padding:12px; border-radius:6px; text-align:center; margin-bottom:10px;'>" +                      "<h2 style='color:#FFFFFF; margin:0; font-size:20px; font-weight:600;'>WakeOnLan Win10 (Custom)</h2>" +                      "<span style='font-size:12px; opacity:0.8;'>Version ${currentVersion} (${timeStamp()})</span></div>"        }        /* Section 1: WOL Target Child Apps */        section("<b>WOL Target Devices</b>") {            app(                name: "childApps",                appName: "WakeOnLan Win10 Instance (Custom)",                namespace: "jshimota",                title: "➕ Add WakeOnLan Device",                multiple: true            )        }        /* Section 2: App Preferences & Logging */        section("<b>App Preferences & Logging Options</b>", hideable: true, hidden: true) {            input name: "showVersionInLabel", type: "bool", title: "Show Version in App Label?", defaultValue: true            paragraph "<hr style='border:0; border-top:1px solid #E0E0E0; margin:8px 0;'/>"            input name: "logInfoEnable", type: "bool", title: "Logging - Enable Info Logging", defaultValue: true, required: true            input name: "logErrorEnable", type: "bool", title: "Logging - Enable Error Logging", defaultValue: true, required: true            input name: "logWarnEnable", type: "bool", title: "Logging - Enable Warning Logging", defaultValue: true, required: true            input name: "logDebugEnable", type: "bool", title: "Logging - Enable Debug Logging", defaultValue: false, required: true            input name: "logTraceEnable", type: "bool", title: "Logging - Enable Trace Logging", defaultValue: false, required: true        }    }}void installed() {    logInfo "Installing Parent App v${version()} (${timeStamp()})..."    initialize()}void updated() {    logInfo "Updating Parent App..."    initialize()}private void initialize() {    updateAppLabel()}private void updateAppLabel() {    Boolean showVersion = getSettingBool("showVersionInLabel", true)    String baseLabel = "WakeOnLan Win10 (Custom)"    if (showVersion) baseLabel += " v${version()}"    if (app.label != baseLabel) {        app.updateLabel(baseLabel)    }}private void logMessage(String level, String msg) {    String lowerLevel = level?.toLowerCase() ?: "info"    String appLabel = app.label ?: app.name ?: "App"    String settingKey = "log${lowerLevel.capitalize()}Enable"    Boolean defaultEnabled = (lowerLevel in ["info", "warn", "error"])    if (getSettingBool(settingKey, defaultEnabled)) {        log."${lowerLevel}" "${appLabel}: ${msg}"    }}private void logInfo(String msg)  { logMessage("info", msg) }private void logDebug(String msg) { logMessage("debug", msg) }private void logWarn(String msg)  { logMessage("warn", msg) }private void logError(String msg) { logMessage("error", msg) }private Boolean getSettingBool(String key, Boolean defaultVal = false) {    def val = settings[key]    if (val == null) return defaultVal    if (val instanceof Boolean) return val    return val.toString().toBoolean()}